<?php
namespace App\Http\Controllers\Api\Master; use App\Http\Controllers\Controller; use App\Models\Master\GrantReportingDeadline; use Illuminate\Http\Request;
class GrantReportingDeadlineController extends Controller {public function index(){return response()->json(['success'=>true,'data'=>GrantReportingDeadline::with('grantAgreement:id,agreement_number,title')->orderBy('due_date')->get()]);}public function store(Request $r){$d=$r->validate(['grant_agreement_id'=>'required|exists:grant_agreements,id','report_type'=>'required|string|max:100','due_date'=>'required|date','status'=>'nullable|in:upcoming,in_progress,submitted,overdue','notes'=>'nullable|string']);return response()->json(['success'=>true,'data'=>GrantReportingDeadline::create($d)],201);}public function update(Request $r,GrantReportingDeadline $grantReportingDeadline){$grantReportingDeadline->update($r->validate(['report_type'=>'sometimes|string|max:100','due_date'=>'sometimes|date','status'=>'sometimes|in:upcoming,in_progress,submitted,overdue','notes'=>'nullable|string']));return response()->json(['success'=>true,'data'=>$grantReportingDeadline]);}public function destroy(GrantReportingDeadline $grantReportingDeadline){$grantReportingDeadline->delete();return response()->json(['success'=>true]);}}
